import{_ as t,o as n,c as o,a3 as a}from"./chunks/framework.I6s8z2kk.js";const g=JSON.parse('{"title":"Clients","description":"","frontmatter":{},"headers":[],"relativePath":"user/admin/clients.md","filePath":"user/admin/clients.md"}'),i={name:"user/admin/clients.md"};function r(s,e,l,c,d,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h1><p><strong>Clients → list</strong> shows every client on the platform. Search by name or phone, open a client to see their details, and export the list if you have the export permission. You can sort it by <strong>Client</strong> (name), <strong>Centers</strong>, <strong>Reservations</strong> or <strong>Joined</strong>; see <a href="./getting-around#lists">Lists</a>.</p><h2 id="how-clients-join" tabindex="-1">How clients join <a class="header-anchor" href="#how-clients-join" aria-label="Permalink to &quot;How clients join&quot;">​</a></h2><p>Clients sign in with their phone number and a one-time code, so there is no password to reset. A client who has not entered a first and last name yet is still <strong>onboarding</strong>.</p><h2 id="generating-a-login-code" tabindex="-1">Generating a login code <a class="header-anchor" href="#generating-a-login-code" aria-label="Permalink to &quot;Generating a login code&quot;">​</a></h2><p>If a client is not receiving the SMS, open the client and choose <strong>Generate OTP</strong>. You get a new 4-digit code to read to them. No SMS is sent, the code is shown only once, it expires after 5 minutes, and any earlier code stops working. This needs the <strong>otps.create</strong> permission.</p><h2 id="per-center-view" tabindex="-1">Per-center view <a class="header-anchor" href="#per-center-view" aria-label="Permalink to &quot;Per-center view&quot;">​</a></h2><p>A center only sees its own clients: people who joined it, or who have a confirmed or completed purchase with it. Admins can open a center&#39;s client list from the center page.</p><h2 id="blocking" tabindex="-1">Blocking <a class="header-anchor" href="#blocking" aria-label="Permalink to &quot;Blocking&quot;">​</a></h2><p>A center can block a client. Blocked clients cannot book that center. Admins can see, add and unblock blocked clients from the center page.</p><h2 id="deleted-clients" tabindex="-1">Deleted clients <a class="header-anchor" href="#deleted-clients" aria-label="Permalink to &quot;Deleted clients&quot;">​</a></h2><p>Deleted clients are hidden everywhere but their history (purchases, reviews) is kept.</p>',12)])])}const m=t(i,[["render",r]]);export{g as __pageData,m as default};
